const M='/home/user/.factory/missions/e194b9e3-6a67-42b9-bfc9-dd4e1ac23b0c';
const W='/home/user/code/EllyaOrg/projects/dalimaray/observatory-wt/s';
const sid='72e5184a-e450-432c-b01c-9c3323bc7617';
const r=await Promise.allSettled([
 tools.Execute({summary:'Feature json',command:`jq '.features|map(select(.id=="s-cli-replay"))|first' ${M}/features.json`,riskLevel:'low'}),
 tools.Execute({summary:'Handoff',command:`f=$(ls -1 ${M}/handoffs | grep ${sid} | sort | tail -n1); cat ${M}/handoffs/$f`,riskLevel:'low'}),
 tools.Execute({summary:'Commits stat',command:`cd ${W} && for c in 830e895 69cb91e 055fc16 cc1fe27 a959cbd 90215d5; do git show --stat --format='%h %ad %s' $c; done; git log --oneline -15`,riskLevel:'low'}),
 tools.Execute({summary:'Arch grep',command:`grep -n -i -E 'child|jsonl|JsonlSource|RawRecord|at_eof|capture.json|MappingVersion|replay' ${M}/architecture.md | head -80`,riskLevel:'low'}),
 tools.Execute({summary:'Contract',command:`grep -n -A8 -E 'VAL-SKEL-0(0[4-8]|13)' ${M}/validation-contract.md`,riskLevel:'low'}),
]);
r.forEach((x,i)=>text(`## ${i}\n`+(x.status==='fulfilled'?x.value.output:String(x.reason))));

