5→use super::{IngestError, RawRecord, Source, SourceKind};
6→use crate::config::IngestConfig;
7→use crate::model::{SessionId, SourcePtr};
8→
9→const KB: u64 = 1024;
10→
11→/// Reads session JSONL files by byte offset. Files are opened read-only and never written.
12→pub struct JsonlSource {
13→    files: Vec<TailState>,
14→    chunk_bytes: usize,
15→}
16→
17→struct TailState {
18→    path: PathBuf,
19→    session_id: SessionId,
20→    /// Offset of the first byte not yet consumed into a line or `partial`.
21→    offset: u64,
22→    /// Bytes after the last newline: a line the writer has not finished.
23→    partial: Vec<u8>,
24→}
25→
26→impl TailState {
27→    fn io_error(&self, source: std::io::Error) -> IngestError {
28→        io_error(&self.path, source)
29→    }
30→
31→    /// Reads at most `chunk_bytes` past `offset` and returns the lines that ended in it.
32→    fn read_chunk(&mut self, chunk_bytes: usize) -> Result<Vec<RawRecord>, IngestError> {
33→        let mut handle = File::open(&self.path).map_err(|source| self.io_error(source))?;
34→        let length = handle
35→            .metadata()
36→            .map_err(|source| self.io_error(source))?
37→            .len();
38→        if length < self.offset {
39→            return Err(IngestError::FileMoved {
40→                path: self.path.clone(),
41→            });
42→        }
43→        handle
44→            .seek(SeekFrom::Start(self.offset))
45→            .map_err(|source| self.io_error(source))?;
46→        let mut buffer = std::mem::take(&mut self.partial);
47→        let carried = buffer.len();
48→        let read = handle
49→            .take(chunk_bytes as u64)
50→            .read_to_end(&mut buffer)
51→            .map_err(|source| self.io_error(source));
52→        let read = match read {
53→            Ok(read) => read,
54→            Err(err) => {
55→                buffer.truncate(carried);
56→                self.partial = buffer;
57→                return Err(err);
58→            }
59→        };
60→
61→        let mut records = Vec::new();
62→        let mut line_start = self.offset - carried as u64;
63→        let mut consumed = 0;
64→        while let Some(newline) = buffer[consumed..].iter().position(|byte| *byte == b'\n') {
65→            let line = buffer[consumed..consumed + newline].to_vec();
66→            let next_start = line_start + newline as u64 + 1;
67→            records.push(self.record(line_start, line));
68→            line_start = next_start;
69→            consumed += newline + 1;
70→        }
71→        self.offset += read as u64;
72→        self.partial = buffer.split_off(consumed);
73→        Ok(records)
74→    }
75→
76→    fn record(&self, byte_offset: u64, bytes: Vec<u8>) -> RawRecord {
77→        RawRecord {
78→            ptr: SourcePtr::Jsonl {
79→                path: self.path.clone(),
80→                byte_offset,
81→                byte_len: u32::try_from(bytes.len()).unwrap_or(u32::MAX),
82→            },
83→            session_id: self.session_id.clone(),
84→            bytes,
85→        }
86→    }
87→}
88→
89→fn io_error(path: &Path, source: std::io::Error) -> IngestError {
90→    IngestError::Io {
91→        path: path.to_owned(),
92→        source,
93→    }
94→}
95→
96→impl JsonlSource {
97→    /// `root` is the orchestrator's session file. Fails when it cannot be read.
98→    pub fn open(root: &Path, cfg: &IngestConfig) -> Result<Self, IngestError> {
99→        let chunk_bytes =
100→            usize::try_from(cfg.tail_chunk_kb.saturating_mul(KB)).unwrap_or(usize::MAX);
101→        let mut source = Self {
102→            files: Vec::new(),
103→            chunk_bytes: chunk_bytes.max(1),
104→        };
105→        source.add_file(root)?;
106→        Ok(source)
107→    }
108→
109→    /// Starts reading another file (a child or a newly discovered session) from its start.
110→    pub fn add_file(&mut self, path: &Path) -> Result<SessionId, IngestError> {
111→        let session_id = session_id_of(path, self.chunk_bytes)?;
112→        self.files.push(TailState {
113→            path: path.to_owned(),
114→            session_id: session_id.clone(),
115→            offset: 0,
116→            partial: Vec::new(),
117→        });
118→        Ok(session_id)
119→    }
120→
121→    /// The session of the file `open` was given.
122→    pub fn root_session_id(&self) -> &SessionId {
123→        &self.files[0].session_id
124→    }
125→
126→    /// Re-reads the line a pointer names.
127→    pub fn read_at(path: &Path, byte_offset: u64, byte_len: u32) -> Result<Vec<u8>, IngestError> {
128→        let mut file = File::open(path).map_err(|source| io_error(path, source))?;
129→        file.seek(SeekFrom::Start(byte_offset))
130→            .map_err(|source| io_error(path, source))?;
131→        let mut line = vec![0; byte_len as usize];
132→        file.read_exact(&mut line)
133→            .map_err(|source| io_error(path, source))?;
134→        Ok(line)
135→    }
136→
137→    /// Returns each unfinished last line as a record. For a file that will not grow again
138→    /// (replay): `next_batch` keeps such a line back because a writer may be mid-line.
139→    pub fn drain_partial(&mut self) -> Vec<RawRecord> {
140→        self.files
141→            .iter_mut()
142→            .filter(|file| !file.partial.is_empty())
143→            .map(|file| {
144→                let bytes = std::mem::take(&mut file.partial);
145→                file.record(file.offset - bytes.len() as u64, bytes)
146→            })
147→            .collect()
148→    }
149→}
150→
151→impl Source for JsonlSource {
152→    fn kind(&self) -> SourceKind {
153→        SourceKind::Jsonl
154→    }
155→
156→    fn next_batch(&mut self) -> Result<Vec<RawRecord>, IngestError> {
157→        let mut batch = Vec::new();
158→        for file in &mut self.files {
159→            batch.extend(file.read_chunk(self.chunk_bytes)?);
160→        }
161→        Ok(batch)
162→    }
163→
164→    fn at_eof(&self) -> bool {
165→        self.files
166→            .iter()
167→            .all(|file| std::fs::metadata(&file.path).is_ok_and(|meta| meta.len() == file.offset))
168→    }
169→}
170→
171→/// The `id` of a leading `session_start` line, else the file stem.
172→fn session_id_of(path: &Path, chunk_bytes: usize) -> Result<SessionId, IngestError> {
173→    let mut head = Vec::new();
174→    File::open(path)
175→        .and_then(|file| file.take(chunk_bytes as u64).read_to_end(&mut head))
176→        .map_err(|source| io_error(path, source))?;
177→    let first_line = head.split(|byte| *byte == b'\n').next().unwrap_or_default();
178→    let started = serde_json::from_slice::<serde_json::Value>(first_line)
179→        .ok()
180→        .filter(|line| line["type"] == "session_start")
181→        .and_then(|line| line["id"].as_str().map(str::to_owned));
182→    let id = started.unwrap_or_else(|| {
183→        path.file_stem()
184→            .map_or_else(String::new, |stem| stem.to_string_lossy().into_owned())
185→    });
186→    Ok(SessionId(id))
187→}
