## crates/observatory-core/src/ingest/capture.rs
1→//! The `<slug>.capture.json` header that sits beside a fixture (architecture §4.2).
2→
3→use std::path::{Path, PathBuf};
4→
5→use serde::Deserialize;
6→
7→use super::IngestError;
8→use crate::mapping::MappingVersion;
9→
10→/// The part of the header the readers use. Other keys are ignored.
11→#[derive(Clone, Debug, PartialEq, Eq, Deserialize)]
12→pub struct CaptureHeader {
13→    pub droid_version: Option<String>,
14→}
15→
16→/// `<dir>/<slug>.jsonl` has its header at `<dir>/<slug>.capture.json`.
17→pub fn capture_path(jsonl_path: &Path) -> PathBuf {
18→    jsonl_path.with_extension("capture.json")
19→}
20→
21→/// `None` when the file has no header, as for a live session directory.
22→pub fn read_capture(jsonl_path: &Path) -> Result<Option<CaptureHeader>, IngestError> {
23→    let path = capture_path(jsonl_path);
24→    let text = match std::fs::read_to_string(&path) {
25→        Ok(text) => text,
26→        Err(source) if source.kind() == std::io::ErrorKind::NotFound => return Ok(None),
27→        Err(source) => return Err(IngestError::Io { path, source }),
28→    };
29→    serde_json::from_str(&text)
30→        .map(Some)
31→        .map_err(|err| IngestError::BadCapture {
32→            path,
33→            message: err.to_string(),
34→        })
35→}
36→
37→/// Mapping version for a session file: chosen by the header's Droid version, `LATEST`
38→/// when there is no header or no version in it.
39→pub fn mapping_version_of(jsonl_path: &Path) -> Result<MappingVersion, IngestError> {
40→    let version = read_capture(jsonl_path)?
41→        .and_then(|header| header.droid_version)
42→        .map_or(MappingVersion::LATEST, |seen| {
43→            MappingVersion::for_droid_version(&seen)
44→        });
45→    Ok(version)
46→}
