## crates/observatory-core/src/mapping/mod.rs
1→//! Raw record to canonical event mapping. Compiled to wasm for the UI (architecture I9).
2→
3→mod v1;
4→mod version;
5→
6→pub use version::MappingVersion;
7→
8→use crate::ingest::RawRecord;
9→use crate::model::{Event, MissionId, ModelId, Role, SessionId, Timestamp};
10→
11→/// What the mapping needs to know about the session a record came from.
12→#[derive(Clone, Debug, PartialEq, Eq)]
13→pub struct SessionMeta {
14→    pub id: SessionId,
15→    pub mission_id: MissionId,
16→    pub role: Role,
17→    pub model: Option<ModelId>,
18→}
19→
20→impl SessionMeta {
21→    /// The session with no `callingSessionId`: it is the mission and its orchestrator.
22→    pub fn root(id: SessionId) -> Self {
23→        Self {
24→            mission_id: MissionId(id.0.clone()),
25→            id,
26→            role: Role::Orchestrator,
27→            model: None,
28→        }
29→    }
30→}
31→
32→pub struct MapContext<'a> {
33→    pub session: &'a SessionMeta,
34→    pub version: MappingVersion,
35→    /// Time given to a record that carries none of its own.
36→    pub fallback_at: Timestamp,
37→}
38→
39→/// Total: every record yields at least one event and the call never panics (invariant I5).
40→pub fn map_record(record: &RawRecord, ctx: &MapContext<'_>) -> Vec<Event> {
41→    match ctx.version {
42→        MappingVersion::V1 => v1::map_record(record, ctx),
43→    }
44→}
45→
46→/// Maps the records of one session in file order. A record without a timestamp takes the
47→/// time of the record before it.
48→pub struct Mapper {
49→    session: SessionMeta,
50→    version: MappingVersion,
51→    last_at: Timestamp,
52→}
53→
54→impl Mapper {
55→    pub fn new(session: SessionMeta, version: MappingVersion) -> Self {
56→        Self {
57→            session,
58→            version,
59→            // Lines before the first timestamped one (`session_start` has none) sort first;
60→            // the epoch says "no time known" without inventing one.
61→            last_at: Timestamp(time::OffsetDateTime::UNIX_EPOCH),
62→        }
63→    }
64→
65→    pub fn map(&mut self, record: &RawRecord) -> Vec<Event> {
66→        let ctx = MapContext {
67→            session: &self.session,
68→            version: self.version,
69→            fallback_at: self.last_at,
70→        };
71→        let events = map_record(record, &ctx);
72→        if let Some(last) = events.last() {
73→            self.last_at = last.at;
74→        }
75→        events
76→    }
77→}
