## crates/observatory-core/src/mapping/v1/mod.rs
1→//! Mapping rules for Droid 0.247 session files. The skeleton knows none of them yet: every
2→//! record becomes `Unknown`, so the unknown count equals the line count.
3→
4→use serde_json::Value;
5→
6→use super::MapContext;
7→use crate::ingest::RawRecord;
8→use crate::model::{Event, EventId, EventKind, Lane, SourcePtr, Timestamp};
9→
10→/// `raw_type` of a line that is not a JSON object with a string `type`.
11→const UNPARSEABLE: &str = "<unparseable>";
12→
13→pub(super) fn map_record(record: &RawRecord, ctx: &MapContext<'_>) -> Vec<Event> {
14→    let line = serde_json::from_slice::<Value>(&record.bytes).ok();
15→    let raw_type = line
16→        .as_ref()
17→        .and_then(|line| line.get("type"))
18→        .and_then(Value::as_str)
19→        .unwrap_or(UNPARSEABLE);
20→    let at = line
21→        .as_ref()
22→        .and_then(|line| line.get("timestamp"))
23→        .and_then(Value::as_str)
24→        .and_then(|text| Timestamp::parse(text).ok())
25→        .unwrap_or(ctx.fallback_at);
26→    let session = ctx.session;
27→
28→    vec![Event {
29→        id: EventId(format!("{}:{}:0", session.id, byte_offset(&record.ptr))),
30→        mission_id: session.mission_id.clone(),
31→        milestone_id: None,
32→        feature_id: None,
33→        lane: Lane::for_role(session.role),
34→        kind: EventKind::Unknown {
35→            raw_type: raw_type.to_owned(),
36→        },
37→        role: session.role,
38→        session_id: Some(session.id.clone()),
39→        model: session.model.clone(),
40→        at,
41→        duration: None,
42→        usage: None,
43→        source: record.ptr.clone(),
44→        mapping_version: ctx.version,
45→    }]
46→}
47→
48→fn byte_offset(ptr: &SourcePtr) -> u64 {
49→    match ptr {
50→        SourcePtr::Jsonl { byte_offset, .. } | SourcePtr::Rpc { byte_offset, .. } => *byte_offset,
51→        SourcePtr::Git { .. } | SourcePtr::GitHub { .. } | SourcePtr::App { .. } => 0,
52→    }
53→}
