1→use serde::{Deserialize, Serialize};
2→
3→/// Version of the rules that turned a raw record into an `Event`. Stored on every event so
4→/// a change of rules is visible in old data.
5→#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
6→#[serde(rename_all = "snake_case")]
7→pub enum MappingVersion {
8→    V1,
9→}
10→
11→impl MappingVersion {
12→    pub const LATEST: MappingVersion = MappingVersion::V1;
13→
14→    /// Picks the rules for the session format of a `droid --version` string. An absent,
15→    /// empty or unrecognised version gets `LATEST`: showing events with the newest rules
16→    /// beats showing none.
17→    pub fn for_droid_version(droid_version: &str) -> MappingVersion {
18→        let seen = droid_version.trim();
19→        if seen == V1_DROID_SERIES
20→            || seen
21→                .strip_prefix(V1_DROID_SERIES)
22→                .is_some_and(|rest| rest.starts_with('.'))
23→        {
24→            MappingVersion::V1
25→        } else {
26→            MappingVersion::LATEST
27→        }
28→    }
29→}
30→
31→/// The Droid release series whose session files the v1 rules were written against.
32→const V1_DROID_SERIES: &str = "0.247";
