1→mod replay;
2→
3→use std::io::{self, BufWriter, ErrorKind, Write};
4→use std::path::PathBuf;
5→use std::process::ExitCode;
6→
7→use clap::{Parser, Subcommand};
8→use observatory_core::config::Config;
9→
10→#[derive(Parser)]
11→#[command(version, about = "Headless replay and inspection of Droid sessions")]
12→struct Cli {
13→    #[command(subcommand)]
14→    command: Command,
15→}
16→
17→#[derive(Subcommand)]
18→enum Command {
19→    /// Print one line per event of a session file, then `unknown events: N`.
20→    Replay {
21→        /// The orchestrator session `.jsonl`.
22→        file: PathBuf,
23→    },
24→}
25→
26→fn main() -> ExitCode {
27→    let cli = Cli::parse();
28→    match run(cli.command) {
29→        Ok(()) => ExitCode::SUCCESS,
30→        Err(err) if is_broken_pipe(err.as_ref()) => ExitCode::SUCCESS,
31→        Err(err) => {
32→            eprintln!("observatory-cli: {err}");
33→            ExitCode::FAILURE
34→        }
35→    }
36→}
37→
38→fn run(command: Command) -> Result<(), Box<dyn std::error::Error>> {
39→    let config = Config::load(None)?;
40→    match command {
41→        Command::Replay { file } => {
42→            let mut out = BufWriter::new(io::stdout().lock());
43→            replay::replay(&file, &config.ingest, &mut out)?;
44→            out.flush()?;
45→            Ok(())
46→        }
47→    }
48→}
49→
50→/// `observatory-cli replay x | head` closes the pipe early; that is not a failure.
51→fn is_broken_pipe(err: &(dyn std::error::Error + 'static)) -> bool {
52→    err.downcast_ref::<io::Error>()
53→        .is_some_and(|err| err.kind() == ErrorKind::BrokenPipe)
54→}
