## crates/observatory-cli/src/replay.rs
1→//! `replay <file>`: attach that stops at the end of the file (D-008).
2→
3→use std::error::Error;
4→use std::io::Write;
5→use std::path::Path;
6→
7→use observatory_core::config::IngestConfig;
8→use observatory_core::ingest::{JsonlSource, Source, mapping_version_of};
9→use observatory_core::mapping::{Mapper, SessionMeta};
10→use observatory_core::model::{Event, EventKind};
11→
12→/// Writes `<time>\t<lane>\t<kind>\t<session>` per event, then `unknown events: N`.
13→/// Only reads `file`; it writes to `out` and nowhere else.
14→pub fn replay(file: &Path, cfg: &IngestConfig, out: &mut impl Write) -> Result<(), Box<dyn Error>> {
15→    let mut source = JsonlSource::open(file, cfg)?;
16→    let version = mapping_version_of(file)?;
17→    let mut mapper = Mapper::new(SessionMeta::root(source.root_session_id().clone()), version);
18→
19→    let mut unknown = 0_u64;
20→    loop {
21→        let batch = source.next_batch()?;
22→        let at_eof = source.at_eof();
23→        let records = if at_eof {
24→            batch.into_iter().chain(source.drain_partial()).collect()
25→        } else {
26→            batch
27→        };
28→        for record in &records {
29→            for event in mapper.map(record) {
30→                unknown += u64::from(matches!(event.kind, EventKind::Unknown { .. }));
31→                writeln!(out, "{}", event_line(&event))?;
32→            }
33→        }
34→        if at_eof {
35→            break;
36→        }
37→    }
38→    writeln!(out, "unknown events: {unknown}")?;
39→    Ok(())
40→}
41→
42→fn event_line(event: &Event) -> String {
43→    let kind = match &event.kind {
44→        EventKind::Unknown { raw_type } => format!("{}({raw_type})", event.kind.prd_name()),
45→        known => known.prd_name().into_owned(),
46→    };
47→    let session = event
48→        .session_id
49→        .as_ref()
50→        .map_or_else(String::new, ToString::to_string);
51→    format!(
52→        "{}\t{} {}\t{kind}\t{session}",
53→        event.at.to_rfc3339_millis(),
54→        event.lane.number(),
55→        event.lane.name()
56→    )
57→}
