93→#[test]
94→fn replayed_events_carry_the_root_session_the_orchestrator_lane_and_the_header_version() {
95→    let (_, events) = replay(&fixture("jsonl"));
96→
97→    let first = events.first().unwrap();
98→    assert_eq!(
99→        first.session_id,
100→        Some(SessionId("e194b9e3-6a67-42b9-bfc9-dd4e1ac23b0c".to_owned()))
101→    );
102→    assert_eq!(first.role, Role::Orchestrator);
103→    assert!(events.iter().all(|e| e.lane == Lane::Orchestrator));
104→    assert!(
105→        events
106→            .iter()
