111→#[test]
112→fn event_time_follows_the_record_and_never_runs_backwards() {
113→    let (_, events) = replay(&fixture("jsonl"));
114→
115→    assert!(events.windows(2).all(|pair| pair[0].at <= pair[1].at));
116→    let timed = events
117→        .iter()
